<?php

defined('ABSPATH')||exit;
final class GCU_Repository{
const MAX_CONTENT_TITLE=240,MAX_CONTENT_BODY=5000,MAX_REASON=500,EVENT_RETENTION_DAYS=90;
private $transaction_depth=0,$deferred_event_ids=array(),$transaction_audit_lock=false,$containment_code='';
public function transaction_active(){return $this->transaction_depth>0;}
public function begin_owned_transaction(){global$wpdb;if($this->transaction_depth>0){$this->transaction_depth++;return true;}if(false===$wpdb->query('START TRANSACTION')){return false;}$this->transaction_depth=1;$this->deferred_event_ids=array();$this->containment_code='';return true;}
public function commit_owned_transaction(){global$wpdb;if($this->transaction_depth<=0){return false;}if($this->transaction_depth>1){$this->transaction_depth--;return true;}if($this->containment_code){$this->rollback_owned_transaction();return false;}$ok=false!==$wpdb->query('COMMIT');$this->transaction_depth=0;$events=$this->deferred_event_ids;$this->deferred_event_ids=array();$this->release_transaction_audit_lock();if(!$ok){$wpdb->query('ROLLBACK');return false;}foreach($events as$event_id){$this->dispatch_outbox($event_id,1);}return true;}
public function rollback_owned_transaction(){global$wpdb;if($this->transaction_depth>0){$wpdb->query('ROLLBACK');}$this->transaction_depth=0;$this->deferred_event_ids=array();$this->release_transaction_audit_lock();$this->apply_containment();return true;}
private function release_transaction_audit_lock(){if($this->transaction_audit_lock){GCU_Hardening::release_db_lock($this->transaction_audit_lock);$this->transaction_audit_lock=false;}}
private function mark_containment($code){$this->containment_code=sanitize_key($code);if(!$this->transaction_active()){$this->apply_containment();}}
private function apply_containment(){if(!$this->containment_code){return;}update_option('gcu_enabled',0,false);GCU_Observability::log('error',$this->containment_code,array('containment'=>'safe_mode'));$this->containment_code='';}
public function active_blocks($slot='',$audience='all',$locale='en-US'){global$wpdb;$t=GCU_Install::tables();$slot=sanitize_key($slot);$audience=GCU_Policy::sanitize_audience($audience);$locale=GCU_Policy::sanitize_locale($locale);$w="b.status='active' AND p.status='active' AND b.locale=%s AND (b.review_due_at IS NULL OR b.review_due_at>UTC_TIMESTAMP())";$a=array($locale);if($slot){$w.=' AND p.slot_key=%s';$a[]=$slot;}if('all'!==$audience){$w.=" AND (p.audience=%s OR p.audience='all') AND (b.audience=%s OR b.audience='all')";$a[]=$audience;$a[]=$audience;}$sql="SELECT b.public_id,b.block_key,b.audience,b.block_type,b.slot_key,b.locale,b.title,b.body,b.cta_label,b.cta_destination,b.claim_keys,b.content_version,p.route_key,p.priority FROM {$t['blocks']} b INNER JOIN {$t['placements']} p ON p.block_key=b.block_key AND p.slot_key=b.slot_key WHERE $w AND b.content_version=(SELECT MAX(b2.content_version) FROM {$t['blocks']} b2 WHERE b2.block_key=b.block_key AND b2.locale=b.locale AND b2.status='active') AND (p.starts_at IS NULL OR p.starts_at<=UTC_TIMESTAMP()) AND (p.ends_at IS NULL OR p.ends_at>UTC_TIMESTAMP()) ORDER BY p.priority ASC,b.id ASC LIMIT 100";$wpdb->last_error='';$r=$wpdb->get_results($wpdb->prepare($sql,$a),ARRAY_A);if(''!==(string)$wpdb->last_error||!is_array($r)){GCU_Observability::log('error','active_blocks_read_failed',array('slot'=>$slot,'locale'=>$locale));return array();}$all_claims=array();foreach($r as&$row){$row['claim_keys']=json_decode((string)$row['claim_keys'],true);if(!is_array($row['claim_keys'])){$row['claim_keys']=array();}$all_claims=array_merge($all_claims,$row['claim_keys']);}unset($row);$valid=$this->public_claims($all_claims);$r=array_values(array_filter($r,static function($row)use($valid){foreach($row['claim_keys']as$key){if(!isset($valid[$key])){return false;}}return GCU_Plugin::instance()->contracts()->placement_ready($row);}));return$r;}
public function public_claims(array$keys){global$wpdb;$keys=array_values(array_unique(array_filter(array_map('sanitize_key',$keys))));if(!$keys){return array();}$t=GCU_Install::tables();$m=implode(',',array_fill(0,count($keys),'%s'));$sql="SELECT claim_key,claim_text,basis,owner_name,source_uri,effective_at,review_due_at,expires_at FROM {$t['claims']} WHERE claim_key IN ($m) AND status='active' AND is_public=1 AND effective_at<=UTC_TIMESTAMP() AND (review_due_at IS NULL OR review_due_at>UTC_TIMESTAMP()) AND (expires_at IS NULL OR expires_at>UTC_TIMESTAMP()) ORDER BY claim_key ASC";$wpdb->last_error='';$rows=$wpdb->get_results($wpdb->prepare($sql,$keys),ARRAY_A);if(''!==(string)$wpdb->last_error||!is_array($rows)){GCU_Observability::log('error','public_claims_read_failed',array('claim_count'=>count($keys)));return array();}$out=array();foreach($rows as$row){$out[$row['claim_key']]=$row;}return$out;}
public function create_content_draft(array$d,$actor){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}$auth=GCU_Capabilities::require_capability(GCU_Capabilities::MANAGE_CONTENT,null,'create_content_draft');if(is_wp_error($auth)){return$auth;}global$wpdb;$t=GCU_Install::tables();$key=sanitize_key(isset($d['block_key'])?$d['block_key']:'');$loc=GCU_Policy::sanitize_locale(isset($d['locale'])?$d['locale']:'en-US');$slot=sanitize_key(isset($d['slot_key'])?$d['slot_key']:'global_clinic_primary');$type=sanitize_key(isset($d['block_type'])?$d['block_type']:'content');$title=GCU_Hardening::bounded_text(sanitize_text_field(isset($d['title'])?$d['title']:''),self::MAX_CONTENT_TITLE);$body=wp_kses_post(isset($d['body'])?$d['body']:'');$plain=trim(wp_strip_all_tags($body));$dest=sanitize_key(isset($d['cta_destination'])?$d['cta_destination']:'');if(!$key||!in_array($slot,array('global_clinic_primary','global_clinic_trust','global_clinic_steps','global_clinic_faq'),true)||!in_array($type,array('hero','trust','steps','faq','content'),true)||''===$title||''===$plain){return new WP_Error('gcu_invalid_content',__('The File 14 content record is incomplete or outside its approved scope.','global-clinic-usp-integration'),array('status'=>400));}$len=function_exists('mb_strlen')?mb_strlen($plain):strlen($plain);if($len>self::MAX_CONTENT_BODY){return new WP_Error('gcu_content_too_long',__('The content body exceeds the approved File 14 bound.','global-clinic-usp-integration'),array('status'=>400));}if($dest&&!array_key_exists($dest,GCU_Plugin::instance()->contracts()->destination_registry())){return new WP_Error('gcu_invalid_destination',__('The CTA destination is not a registered File 14 contract.','global-clinic-usp-integration'),array('status'=>400));}$claims=array_values(array_unique(array_filter(array_map('sanitize_key',isset($d['claim_keys'])&&is_array($d['claim_keys'])?$d['claim_keys']:array()))));if(count($claims)>20){return new WP_Error('gcu_claim_set_too_large',__('Too many claims were attached to one content block.','global-clinic-usp-integration'),array('status'=>400));}$lock=GCU_Hardening::acquire_db_lock('content:'.$key.':'.$loc);if(!$lock){return new WP_Error('gcu_content_lock_busy',__('Another content version is being created. Please retry.','global-clinic-usp-integration'),array('status'=>409));}try{if(!$this->begin_owned_transaction()){return new WP_Error('gcu_content_transaction_failed',__('The content transaction could not start.','global-clinic-usp-integration'),array('status'=>500));}$wpdb->last_error='';$latest_raw=$wpdb->get_var($wpdb->prepare("SELECT MAX(content_version) FROM {$t['blocks']} WHERE block_key=%s AND locale=%s",$key,$loc));if(''!==(string)$wpdb->last_error){$this->rollback_owned_transaction();return new WP_Error('gcu_content_version_read_failed',__('The next content version could not be determined safely.','global-clinic-usp-integration'),array('status'=>503));}$latest=(int)$latest_raw;$now=current_time('mysql',true);$r=array('public_id'=>wp_generate_uuid4(),'block_key'=>$key,'audience'=>GCU_Policy::sanitize_audience(isset($d['audience'])?$d['audience']:'all'),'block_type'=>$type,'slot_key'=>$slot,'locale'=>$loc,'title'=>$title,'body'=>$body,'cta_label'=>GCU_Hardening::bounded_text(sanitize_text_field(isset($d['cta_label'])?$d['cta_label']:''),120),'cta_destination'=>$dest,'claim_keys'=>wp_json_encode($claims),'status'=>'draft','content_version'=>$latest+1,'created_by'=>absint($actor),'created_at'=>$now,'updated_at'=>$now);if(false===$wpdb->insert($t['blocks'],$r)){$this->rollback_owned_transaction();return new WP_Error('gcu_write_failed',__('The content version could not be created.','global-clinic-usp-integration'),array('status'=>500));}if(false===$this->audit('content_created','content_block',$r['public_id'],'content_governance','',array(),$r)){$this->rollback_owned_transaction();return new WP_Error('gcu_audit_required',__('The content version was not committed because its audit record could not be written.','global-clinic-usp-integration'),array('status'=>503));}$result=$this->content_by_public_id($r['public_id']);if(!is_array($result)||!isset($result['public_id'],$result['status'],$result['content_version'])||!hash_equals((string)$r['public_id'],(string)$result['public_id'])||'draft'!==(string)$result['status']||(int)$r['content_version']!==(int)$result['content_version']){$this->rollback_owned_transaction();return new WP_Error('gcu_content_readback_failed',__('The content version could not be verified before commit.','global-clinic-usp-integration'),array('status'=>503));}if(!$this->commit_owned_transaction()){return new WP_Error('gcu_content_commit_failed',__('The content version could not be committed safely.','global-clinic-usp-integration'),array('status'=>500));}return$result;}finally{GCU_Hardening::release_db_lock($lock);}}
public function transition($machine,$id,$expected,$target,$reason=''){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}$machine=sanitize_key($machine);$target=sanitize_key($target);$map=array('copy'=>array('table'=>'blocks','cap'=>GCU_Capabilities::MANAGE_CONTENT),'placement'=>array('table'=>'placements','cap'=>GCU_Capabilities::MANAGE_PLACEMENTS),'experiment'=>array('table'=>'experiments','cap'=>GCU_Capabilities::MANAGE_EXPERIMENTS));if(!isset($map[$machine])){return new WP_Error('gcu_invalid_machine',__('Unknown workflow type.','global-clinic-usp-integration'),array('status'=>400));}$auth=GCU_Capabilities::require_capability($map[$machine]['cap'],$id,'transition_'.$machine);if(is_wp_error($auth)){return$auth;}if(('copy'===$machine&&in_array($target,array('founder_approved','active','withdrawn'),true))||('placement'===$machine&&'active'===$target)||('experiment'===$machine&&in_array($target,array('approved','running','adopted'),true))){$a=GCU_Capabilities::require_capability(GCU_Capabilities::APPROVE_CLAIMS,$id,'governed_approval');if(is_wp_error($a)){return$a;}}global$wpdb;$t=GCU_Install::tables();$table=$t[$map[$machine]['table']];$wpdb->last_error='';$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM `$table` WHERE public_id=%s",sanitize_text_field($id)),ARRAY_A);if(''!==(string)$wpdb->last_error){return new WP_Error('gcu_workflow_read_failed',__('The workflow record could not be verified safely. Retry later.','global-clinic-usp-integration'),array('status'=>503));}if(!$row){return new WP_Error('gcu_not_found',__('The requested record was not found.','global-clinic-usp-integration'),array('status'=>404));}if((int)$row['row_version']!==(int)$expected){return new WP_Error('gcu_version_conflict',__('The record changed. Reload it before retrying.','global-clinic-usp-integration'),array('status'=>409,'current_version'=>(int)$row['row_version']));}if(!GCU_Policy::transition_allowed($machine,$row['status'],$target)){return new WP_Error('gcu_invalid_transition',__('This state transition is not allowed.','global-clinic-usp-integration'),array('status'=>409));}$v=$this->validate_transition_target($machine,$row,$target);if(is_wp_error($v)){return$v;}$scope='workflow:'.$machine.':'.('copy'===$machine?$row['block_key'].':'.$row['locale']:$id);$lock=GCU_Hardening::acquire_db_lock($scope);if(!$lock){return new WP_Error('gcu_workflow_lock_busy',__('Another workflow update is in progress. Please retry.','global-clinic-usp-integration'),array('status'=>409));}try{if(!$this->begin_owned_transaction()){return new WP_Error('gcu_transaction_failed',__('The workflow transaction could not start.','global-clinic-usp-integration'),array('status'=>500));}$u=array('status'=>$target,'row_version'=>(int)$row['row_version']+1,'updated_at'=>current_time('mysql',true));if('copy'===$machine&&'founder_approved'===$target){$u['approved_by']=get_current_user_id();$u['approved_at']=current_time('mysql',true);$u['review_due_at']=gmdate('Y-m-d H:i:s',time()+GCU_Policy::COPY_REVIEW_DAYS*DAY_IN_SECONDS);}if('experiment'===$machine&&'approved'===$target){$u['approved_by']=get_current_user_id();}$done=$wpdb->update($table,$u,array('id'=>(int)$row['id'],'row_version'=>(int)$expected));if(1!==$done){$this->rollback_owned_transaction();return new WP_Error('gcu_concurrent_update',__('A concurrent update prevented this transition.','global-clinic-usp-integration'),array('status'=>409));}if('copy'===$machine&&'active'===$target){$n=current_time('mysql',true);$wpdb->last_error='';$older=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['blocks']} WHERE block_key=%s AND locale=%s AND id<>%d AND status='active' ORDER BY id ASC",$row['block_key'],$row['locale'],(int)$row['id']),ARRAY_A);if(''!==(string)$wpdb->last_error){$this->rollback_owned_transaction();return new WP_Error('gcu_supersede_read_failed',__('Older active content versions could not be verified before supersession.','global-clinic-usp-integration'),array('status'=>503));}$sup=$wpdb->query($wpdb->prepare("UPDATE {$t['blocks']} SET status='superseded',row_version=row_version+1,updated_at=%s WHERE block_key=%s AND locale=%s AND id<>%d AND status='active'",$n,$row['block_key'],$row['locale'],(int)$row['id']));if(false===$sup||$sup!==count(is_array($older)?$older:array())){$this->rollback_owned_transaction();return new WP_Error('gcu_supersede_failed',__('Older active content versions could not be superseded safely.','global-clinic-usp-integration'),array('status'=>500));}foreach(is_array($older)?$older:array()as$old){$after=$old;$after['status']='superseded';$after['row_version']=(int)$old['row_version']+1;$after['updated_at']=$n;if(false===$this->audit('content_superseded','copy',$old['public_id'],'workflow_governance','activated_new_version',$old,$after)||false===$this->publish_event('ClinicUSPContentPublished.v1',array('public_id'=>$old['public_id'],'status'=>'superseded'))){$this->rollback_owned_transaction();return new WP_Error('gcu_supersede_governance_failed',__('Superseded content could not be committed with complete audit and owner-event evidence.','global-clinic-usp-integration'),array('status'=>503));}}}if(false===$this->audit('state_transition',$machine,$id,'workflow_governance',$reason,$row,array_merge($row,$u))){$this->rollback_owned_transaction();return new WP_Error('gcu_audit_required',__('The workflow transition was not committed because its audit record could not be written.','global-clinic-usp-integration'),array('status'=>503));}if('copy'===$machine&&in_array($target,array('active','withdrawn','superseded'),true)){if(false===$this->publish_event('ClinicUSPContentPublished.v1',array('public_id'=>$id,'status'=>$target))){$this->rollback_owned_transaction();return new WP_Error('gcu_outbox_required',__('The workflow transition was not committed because its owner event could not be queued.','global-clinic-usp-integration'),array('status'=>503));}}if(!$this->commit_owned_transaction()){return new WP_Error('gcu_commit_failed',__('The workflow transaction could not be committed.','global-clinic-usp-integration'),array('status'=>500));}return array('public_id'=>$id,'status'=>$target,'row_version'=>$u['row_version']);}finally{GCU_Hardening::release_db_lock($lock);}}
private function validate_transition_target($machine,array$row,$target){global$wpdb;$t=GCU_Install::tables();if('copy'===$machine&&in_array($target,array('founder_approved','active'),true)){$c=json_decode((string)$row['claim_keys'],true);$c=is_array($c)?array_values(array_unique(array_filter(array_map('sanitize_key',$c)))):array();if($c&&count($this->public_claims($c))!==count($c)){return new WP_Error('gcu_claim_dependency_unready',__('All linked claims must be current, public and active before this copy can be approved.','global-clinic-usp-integration'),array('status'=>409));}if($row['cta_destination']){$d=GCU_Plugin::instance()->contracts()->destination($row['cta_destination']);if(empty($d['available'])){return new WP_Error('gcu_destination_unready',__('The linked destination is not ready for active conversion copy.','global-clinic-usp-integration'),array('status'=>409));}}if(!class_exists('GCU_Future_Policy')||!class_exists('GCU_Future_Intelligence')){return new WP_Error('gcu_future_governance_unavailable',__('Future Conversion and Trust governance is unavailable, so governed copy cannot be approved safely.','global-clinic-usp-integration'),array('status'=>503));}$wpdb->last_error='';$previous=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['blocks']} WHERE block_key=%s AND locale=%s AND status='active' AND id<>%d ORDER BY content_version DESC LIMIT 1",$row['block_key'],$row['locale'],(int)$row['id']),ARRAY_A);if(''!==(string)$wpdb->last_error){return new WP_Error('gcu_copy_preflight_read_failed',__('Previous active copy could not be verified for governed preflight.','global-clinic-usp-integration'),array('status'=>503));}$preflight=GCU_Future_Policy::copy_preflight($row,is_array($previous)?$previous:array());$parity=GCU_Future_Intelligence::parity_status();if(empty($preflight['safe'])||empty($parity['ok'])){return new WP_Error('gcu_future_copy_preflight_failed',__('Future Conversion and Trust governance blocked this copy until its semantic, dark-pattern and policy-parity risks are corrected.','global-clinic-usp-integration'),array('status'=>409,'preflight'=>$preflight,'parity'=>$parity));}}if('placement'===$machine&&'active'===$target){$wpdb->last_error='';$b=$wpdb->get_row($wpdb->prepare("SELECT id,slot_key,audience FROM {$t['blocks']} WHERE block_key=%s AND status='active' ORDER BY content_version DESC LIMIT 1",$row['block_key']),ARRAY_A);if(''!==(string)$wpdb->last_error){return new WP_Error('gcu_placement_dependency_read_failed',__('The placement content dependency could not be verified safely.','global-clinic-usp-integration'),array('status'=>503));}$block_audience=$b?GCU_Policy::sanitize_audience($b['audience']):'';$placement_audience=GCU_Policy::sanitize_audience(isset($row['audience'])?$row['audience']:'all');$audience_ok=$b&&('all'===$block_audience||$block_audience===$placement_audience);if(!$b||$b['slot_key']!==$row['slot_key']||!$audience_ok||!GCU_Plugin::instance()->contracts()->placement_ready($row)){return new WP_Error('gcu_placement_unready',__('The active block, audience contract or File 20 slot is not ready.','global-clinic-usp-integration'),array('status'=>409));}}if('experiment'===$machine&&in_array($target,array('approved','running'),true)){foreach(array('hypothesis','variants','guardrails','success_metric','sample_policy','privacy_policy','ends_at')as$f){if(empty($row[$f])){return new WP_Error('gcu_experiment_incomplete',__('The experiment is missing required governance fields.','global-clinic-usp-integration'),array('status'=>409));}}$end=strtotime($row['ends_at'].' UTC');if(!$end||$end<=time()||$end>time()+90*DAY_IN_SECONDS){return new WP_Error('gcu_experiment_window_invalid',__('The experiment end date must be within the approved 90-day window.','global-clinic-usp-integration'),array('status'=>409));}if(!class_exists('GCU_Future_Policy')||!class_exists('GCU_Future_Intelligence')){return new WP_Error('gcu_future_governance_unavailable',__('Future Conversion and Trust governance is unavailable, so this experiment cannot be approved safely.','global-clinic-usp-integration'),array('status'=>503));}$preflight=GCU_Future_Policy::experiment_preflight(json_decode((string)$row['variants'],true)?:array(),json_decode((string)$row['guardrails'],true)?:array(),$row['sample_policy'],$row['privacy_policy']);$parity=GCU_Future_Intelligence::parity_status();if(empty($preflight['safe'])||empty($parity['ok'])){return new WP_Error('gcu_future_experiment_preflight_failed',__('The experiment failed the native Future Conversion and Trust safety preflight.','global-clinic-usp-integration'),array('status'=>409,'preflight'=>$preflight,'parity'=>$parity));}}return true;}
public function create_placement(array$d){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}$a=GCU_Capabilities::require_capability(GCU_Capabilities::MANAGE_PLACEMENTS,null,'create_placement');if(is_wp_error($a)){return$a;}$key=sanitize_key(isset($d['placement_key'])?$d['placement_key']:'');$block=sanitize_key(isset($d['block_key'])?$d['block_key']:'');$route=sanitize_key(isset($d['route_key'])?$d['route_key']:'global_clinic');$slot=sanitize_key(isset($d['slot_key'])?$d['slot_key']:'');if(!$key||!$block||'global_clinic'!==$route||!in_array($slot,array('global_clinic_primary','global_clinic_trust','global_clinic_steps','global_clinic_faq'),true)){return new WP_Error('gcu_invalid_placement',__('The placement contract is incomplete or outside File 14 ownership.','global-clinic-usp-integration'),array('status'=>400));}$starts=$this->sanitize_datetime(isset($d['starts_at'])?$d['starts_at']:'');$ends=$this->sanitize_datetime(isset($d['ends_at'])?$d['ends_at']:'');if($starts&&$ends&&strtotime($ends.' UTC')<=strtotime($starts.' UTC')){return new WP_Error('gcu_invalid_placement_window',__('Placement end time must be after its start time.','global-clinic-usp-integration'),array('status'=>400));}global$wpdb;$t=GCU_Install::tables();if(!$this->begin_owned_transaction()){return new WP_Error('gcu_placement_transaction_failed',__('The placement transaction could not start.','global-clinic-usp-integration'),array('status'=>500));}$now=current_time('mysql',true);$r=array('public_id'=>wp_generate_uuid4(),'placement_key'=>$key,'block_key'=>$block,'route_key'=>$route,'slot_key'=>$slot,'audience'=>GCU_Policy::sanitize_audience(isset($d['audience'])?$d['audience']:'all'),'priority'=>max(1,min(1000,absint(isset($d['priority'])?$d['priority']:100))),'status'=>'planned','starts_at'=>$starts,'ends_at'=>$ends,'created_by'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now);if(false===$wpdb->insert($t['placements'],$r)){$this->rollback_owned_transaction();return new WP_Error('gcu_placement_write_failed',__('The placement could not be created.','global-clinic-usp-integration'),array('status'=>409));}if(false===$this->audit('placement_created','placement',$r['public_id'],'placement_governance','',array(),$r)){$this->rollback_owned_transaction();return new WP_Error('gcu_audit_required',__('The placement was not committed because its audit record could not be written.','global-clinic-usp-integration'),array('status'=>503));}$result=$this->record_by_public_id('placements',$r['public_id']);if(!is_array($result)||!isset($result['public_id'],$result['status'])||!hash_equals((string)$r['public_id'],(string)$result['public_id'])||'planned'!==(string)$result['status']){$this->rollback_owned_transaction();return new WP_Error('gcu_placement_readback_failed',__('The placement could not be verified before commit.','global-clinic-usp-integration'),array('status'=>503));}if(!$this->commit_owned_transaction()){return new WP_Error('gcu_placement_commit_failed',__('The placement could not be committed safely.','global-clinic-usp-integration'),array('status'=>500));}return$result;}
