public function withdraw_claim($claim,$expected,$reason){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}$a=GCU_Capabilities::require_capability(GCU_Capabilities::APPROVE_CLAIMS,$claim,'withdraw_claim');if(is_wp_error($a)){return$a;}$reason=GCU_Hardening::bounded_text(sanitize_textarea_field($reason),self::MAX_REASON);if((function_exists('mb_strlen')?mb_strlen($reason):strlen($reason))<8){return new WP_Error('gcu_reason_required',__('A meaningful bounded withdrawal reason is required.','global-clinic-usp-integration'),array('status'=>400));}global$wpdb;$t=GCU_Install::tables();$key=sanitize_key($claim);$lock=GCU_Hardening::acquire_db_lock('claim:'.$key);if(!$lock){return new WP_Error('gcu_claim_lock_busy',__('Another claim update is in progress.','global-clinic-usp-integration'),array('status'=>409));}try{$wpdb->last_error='';$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['claims']} WHERE claim_key=%s",$key),ARRAY_A);if(''!==(string)$wpdb->last_error){return new WP_Error('gcu_claim_read_failed',__('The claim could not be verified safely. Retry later.','global-clinic-usp-integration'),array('status'=>503));}if(!$row){return new WP_Error('gcu_claim_not_found',__('The claim was not found.','global-clinic-usp-integration'),array('status'=>404));}if((int)$row['row_version']!==(int)$expected){return new WP_Error('gcu_version_conflict',__('The claim changed. Reload it before retrying.','global-clinic-usp-integration'),array('status'=>409));}if(!$this->begin_owned_transaction()){return new WP_Error('gcu_claim_transaction_failed',__('Claim withdrawal transaction could not start.','global-clinic-usp-integration'),array('status'=>500));}$h=array('claim_key'=>$key,'row_version'=>(int)$row['row_version'],'status'=>$row['status'],'claim_hash'=>hash('sha256',wp_json_encode($row)),'reason'=>$reason,'snapshot'=>wp_json_encode($row),'actor_id'=>get_current_user_id(),'created_at'=>current_time('mysql',true));$ins=$wpdb->query($wpdb->prepare("INSERT INTO {$t['claim_history']} (claim_key,row_version,status,claim_hash,reason,snapshot,actor_id,created_at) VALUES (%s,%d,%s,%s,%s,%s,%d,%s)",$h['claim_key'],$h['row_version'],$h['status'],$h['claim_hash'],$h['reason'],$h['snapshot'],$h['actor_id'],$h['created_at']));if(false===$ins){$wpdb->last_error='';$existing_history=$wpdb->get_row($wpdb->prepare("SELECT status,claim_hash,snapshot FROM {$t['claim_history']} WHERE claim_key=%s AND row_version=%d LIMIT 1",$h['claim_key'],$h['row_version']),ARRAY_A);if(''!==(string)$wpdb->last_error){$this->rollback_owned_transaction();return new WP_Error('gcu_claim_history_read_failed',__('Claim history could not be verified after a write conflict.','global-clinic-usp-integration'),array('status'=>503));}$same_history=is_array($existing_history)&&hash_equals((string)$existing_history['status'],(string)$h['status'])&&hash_equals((string)$existing_history['claim_hash'],(string)$h['claim_hash'])&&hash_equals(hash('sha256',(string)$existing_history['snapshot']),hash('sha256',(string)$h['snapshot']));if(!$same_history){$this->rollback_owned_transaction();return new WP_Error('gcu_claim_history_failed',__('Claim history could not be recorded safely.','global-clinic-usp-integration'),array('status'=>500));}}$u=array('status'=>'withdrawn','is_public'=>0,'row_version'=>(int)$row['row_version']+1,'updated_at'=>current_time('mysql',true));$done=$wpdb->update($t['claims'],$u,array('id'=>(int)$row['id'],'row_version'=>(int)$expected));if(1!==$done){$this->rollback_owned_transaction();return new WP_Error('gcu_claim_withdraw_failed',__('The claim could not be withdrawn atomically.','global-clinic-usp-integration'),array('status'=>409));}if(false===$this->audit('claim_withdrawn','claim',$key,'claim_governance',$reason,$row,array_merge($row,$u))||false===$this->publish_event('ClinicUSPClaimWithdrawn.v1',array('claim_key'=>$key))){$this->rollback_owned_transaction();return new WP_Error('gcu_claim_governance_commit_failed',__('The claim was not commi