public function issue_event_token($purpose='measurement'){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}if(!GCU_Privacy::measurement_allowed()||GCU_Hardening::is_sensitive_path()){return new WP_Error('gcu_measurement_not_allowed',__('Measurement is not permitted in this context.','global-clinic-usp-integration'),array('status'=>403));}$rate=$this->consume_rate_limit('token-issue',30);if(is_wp_error($rate)){return$rate;}global$wpdb;$t=GCU_Install::tables();$id=wp_generate_uuid4();try{$secret=bin2hex(random_bytes(24));}catch(Exception$e){return new WP_Error('gcu_entropy_unavailable',__('A secure event token could not be created.','global-clinic-usp-integration'),array('status'=>503));}$token=$id.'.'.$secret;$r=array('token_id'=>$id,'token_hash'=>hash('sha256',$token),'purpose'=>sanitize_key($purpose),'expires_at'=>gmdate('Y-m-d H:i:s',time()+GCU_Policy::EVENT_TOKEN_TTL),'created_at'=>current_time('mysql',true));if(false===$wpdb->insert($t['event_tokens'],$r)){return new WP_Error('gcu_event_token_write_failed',__('The event token could not be issued.','global-clinic-usp-integration'),array('status'=>500));}return array('token'=>$token,'expires_in'=>GCU_Policy::EVENT_TOKEN_TTL);}
public function validate_event_token($token,$purpose='measurement'){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}$token=sanitize_text_field((string)$token);if(!preg_match('/^[a-f0-9\-]{36}\.[a-f0-9]{48}$/',$token)){return new WP_Error('gcu_event_token_invalid',__('A valid event token is required.','global-clinic-usp-integration'),array('status'=>403));}global$wpdb;$t=GCU_Install::tables();$wpdb->last_error='';$ok=$wpdb->get_var($wpdb->prepare("SELECT token_id FROM {$t['event_tokens']} WHERE token_hash=%s AND purpose=%s AND consumed_at IS NULL AND expires_at>UTC_TIMESTAMP() LIMIT 1",hash('sha256',$token),sanitize_key($purpose)));if(''!==(string)$wpdb->last_error){return new WP_Error('gcu_event_token_read_failed',__('The event token could not be verified safely.','global-clinic-usp-integration'),array('status'=>503));}return $ok?true:new WP_Error('gcu_event_token_expired',__('The event token expired or was already used.','global-clinic-usp-integration'),array('status'=>403));}
public function consume_event_token($token,$purpose='measurement'){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}$token=sanitize_text_field((string)$token);if(!preg_match('/^[a-f0-9\-]{36}\.[a-f0-9]{48}$/',$token)){return new WP_Error('gcu_event_token_invalid',__('A valid event token is required.','global-clinic-usp-integration'),array('status'=>403));}global$wpdb;$t=GCU_Install::tables();$done=$wpdb->query($wpdb->prepare("UPDATE {$t['event_tokens']} SET consumed_at=%s WHERE token_hash=%s AND purpose=%s AND consumed_at IS NULL AND expires_at>UTC_TIMESTAMP()",current_time('mysql',true),hash('sha256',$token),sanitize_key($purpose)));if(false===$done){return new WP_Error('gcu_event_token_store_failed',__('The event token state could not be verified safely. Retry later.','global-clinic-usp-integration'),array('status'=>503));}return 1===$done?true:new WP_Error('gcu_event_token_expired',__('The event token expired or was already used.','global-clinic-usp-integration'),array('status'=>403));}
public function consume_rate_limit($scope,$limit=60){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}global$wpdb;$t=GCU_Install::tables();$id=is_user_logged_in()?'u:'.get_current_user_id():'a:'.(isset($_SERVER['REMOTE_ADDR'])?sanitize_text_field(wp_unslash($_SERVER['REMOTE_ADDR'])):'unknown');$bucket=hash_hmac('sha256',sanitize_key($scope).'|'.$id.'|'.gmdate('YmdHi'),wp_salt('auth'));$sql=$wpdb->prepare("INSERT INTO {$t['rate_limits']} (bucket_key,counter,expires_at,updated_at) VALUES (%s,1,%s,%s) ON DUPLICATE KEY UPDATE counter=counter+1,expires_at=VALUES(expires_at),updated_at=VALUES(updated_at)",$bucket,gmdate('Y-m-d H:i:s',time()+120),current_time('mysql',true));if(false===$wpdb->query($sql)){return new WP_Error('gcu_rate_limit_store_failed',__('The request could not be rate-limited safely.','global-clinic-usp-integration'),array('status'=>503));}$raw=$wpdb->get_var($wpdb->prepare("SELECT counter FROM {$t['rate_limits']} WHERE bucket_key=%s",$bucket));if(null===$raw){return new WP_Error('gcu_rate_limit_read_failed',__('The request could not be rate-limited safely.','global-clinic-usp-integration'),array('status'=>503));}$count=(int)$raw;return$count>max(1,(int)$limit)?new WP_Error('gcu_rate_limited',__('Too many requests. Please retry later.','global-clinic-usp-integration'),array('status'=>429)):$count;}
public function record_event(array$d,$token=''){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}if(!GCU_Privacy::measurement_allowed()||GCU_Hardening::is_sensitive_path()){return new WP_Error('gcu_consent_required',__('Measurement consent is required and this route must be eligible.','global-clinic-usp-integration'),array('status'=>403));}$rate=$this->consume_rate_limit('measurement',GCU_Policy::EVENT_RATE_LIMIT);if(is_wp_error($rate)){return$rate;}$stage=sanitize_key(isset($d['stage'])?$d['stage']:'');if(!in_array($stage,array('impression','cta_selected','destination_loaded','application_started','booking_started'),true)){return new WP_Error('gcu_invalid_stage',__('Unknown funnel stage.','global-clinic-usp-integration'),array('status'=>400));}$dest=sanitize_key(isset($d['destination'])?$d['destination']:'');$reg=GCU_Plugin::instance()->contracts()->destination_registry();if(in_array($stage,array('cta_selected','destination_loaded','application_started','booking_started'),true)&&''===$dest){return new WP_Error('gcu_event_destination_required',__('This funnel stage requires a canonical destination.','global-clinic-usp-integration'),array('status'=>400));}if($dest&&!isset($reg[$dest])){return new WP_Error('gcu_invalid_destination',__('Unknown funnel destination.','global-clinic-usp-integration'),array('status'=>400));}if(('application_started'===$stage&&'doctor_onboarding'!==$dest)||('booking_started'===$stage&&'clinic'!==$dest)){return new WP_Error('gcu_stage_destination_mismatch',__('The funnel stage does not match its owner destination.','global-clinic-usp-integration'),array('status'=>400));}global$wpdb;$t=GCU_Install::tables();$c=GCU_Policy::sanitize_campaign(isset($d['campaign'])&&is_array($d['campaign'])?$d['campaign']:array());$id=isset($d['event_id'])&&wp_is_uuid($d['event_id'])?$d['event_id']:wp_generate_uuid4();$subject=GCU_Plugin::instance()->privacy()->event_subject_hash();if(!preg_match('/^[a-f0-9]{64}$/',(string)$subject)){return new WP_Error('gcu_event_subject_unavailable',__('A stable privacy-safe measurement subject could not be established.','global-clinic-usp-integration'),array('status'=>503));}if(!$this->begin_owned_transaction()){return new WP_Error('gcu_event_transaction_failed',__('The conversion event transaction could not start.','global-clinic-usp-integration'),array('status'=>503));}if(''!==(string)$token){$consumed=$this->consume_event_token($token,'measurement');if(is_wp_error($consumed)){$this->rollback_owned_transaction();return$consumed;}}$ins=$wpdb->query($wpdb->prepare("INSERT INTO {$t['events']} (event_id,event_type,event_version,funnel_stage,destination_key,subject_hash,source_value,medium_value,campaign_value,ref_value,consent_state,occurred_at,created_at) VALUES (%s,'ClinicUSPFunnelEvent',1,%s,%s,%s,%s,%s,%s,%s,'granted',%s,%s)",$id,$stage,$dest,$subject,$c['source'],$c['medium'],$c['campaign'],$c['ref'],current_time('mysql',true),current_time('mysql',true)));if(false===$ins){$wpdb->last_error='';$existing=$wpdb->get_row($wpdb->prepare("SELECT funnel_stage,destination_key,subject_hash,source_value,medium_value,campaign_value,ref_value FROM {$t['events']} WHERE event_id=%s LIMIT 1",$id),ARRAY_A);if(''!==(string)$wpdb->last_error){$this->rollback_owned_transaction();return new WP_Error('gcu_event_duplicate_query_failed',__('The event identity could not be verified after a write conflict. Retry later.','global-clinic-usp-integration'),array('status'=>503));}$expected=array('funnel_stage'=>$stage,'destination_key'=>$dest,'subject_hash'=>$subject,'source_value'=>$c['source'],'medium_value'=>$c['medium'],'campaign_value'=>$c['campaign'],'ref_value'=>$c['ref']);$same=is_array($existing);if($same){foreach($expected as$k=>$v){if(!array_key_exists($k,$existing)||!hash_equals((string)$existing[$k],(string)$v)){$same=false;break;}}}if($same){$ins=0;}elseif($existing){$this->rollback_owned_transaction();return new WP_Error('gcu_event_identity_conflict',__('This conversion event identifier is already bound to different event data. Use a new event identifier.','global-clinic-usp-integration'),array('status'=>409));}else{$this->rollback_owned_transaction();return new WP_Error('gcu_event_write_failed',__('The event could not be recorded.','global-clinic-usp-integration'),array('status'=>500));}}if('cta_selected'===$stage&&1===$ins&&false===$this->publish_event('ClinicUSPCTASelected.v1',array('source_event_id'=>$id,'destination'=>$dest))){$this->rollback_owned_transaction();return new WP_Error('gcu_event_outbox_failed',__('The conversion event could not be durably queued for its owner event contract.','global-clinic-usp-integration'),array('status'=>503));}if(!$this->commit_owned_transaction()){$this->rollback_owned_transaction();return new WP_Error('gcu_event_commit_failed',__('The conversion event could not be committed safely.','global-clinic-usp-integration'),array('status'=>503));}return array('event_id'=>$id,'deduplicated'=>0===$ins);}

public function funnel_summary($days=30){$a=GCU_Capabilities::require_capability(GCU_Capabilities::VIEW_ANALYTICS,null,'view_funnel_summary');if(is_wp_error($a)){return$a;}global$wpdb;$days=max(1,min(self::EVENT_RETENTION_DAYS,absint($days)));$t=GCU_Install::tables();$rows=$wpdb->get_results($wpdb->prepare("SELECT funnel_stage,COUNT(*) AS total FROM {$t['events']} WHERE occurred_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL %d DAY) GROUP BY funnel_stage ORDER BY funnel_stage",$days),ARRAY_A);$total=array_sum(array_map(static function($r){return(int)$r['total'];},is_array($rows)?$rows:array()));if($total<10){return array('suppressed'=>true,'threshold'=>10,'days'=>$days,'stages'=>array(),'suppressed_stages'=>array());}$safe=array();$suppressed=array();foreach(is_array($rows)?$rows:array()as$row){$n=(int)$row['total'];if($n<10){$suppressed[]=sanitize_key($row['funnel_stage']);$row['total']=null;$row['suppressed']=true;}else{$row['total']=$n;$row['suppressed']=false;}$safe[]=$row;}return array('suppressed'=>false,'threshold'=>10,'days'=>$days,'stages'=>$safe,'suppressed_stages'=>$suppressed);}
