public function run_idempotent_command($name,$supplied,callable$callback,$request_hash=''){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return$ready;}if(!preg_match('/^[a-f0-9]{64}$/',(string)$request_hash)){return new WP_Error('gcu_request_fingerprint_required',__('A canonical request fingerprint is required for this idempotent command.','global-clinic-usp-integration'),array('status'=>400));}global$wpdb;$t=GCU_Install::tables();$key=GCU_Hardening::command_key($name,$supplied);$now=current_time('mysql',true);$ins=$wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$t['commands']} (command_key,command_name,request_hash,actor_id,status,attempts,locked_at,created_at,updated_at) VALUES (%s,%s,%s,%d,'processing',1,%s,%s,%s)",$key,sanitize_key($name),$request_hash,get_current_user_id(),$now,$now,$now));if(false===$ins){return new WP_Error('gcu_command_store_failed',__('The idempotent command state could not be stored.','global-clinic-usp-integration'),array('status'=>503));}if(0===$ins){$wpdb->last_error='';$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['commands']} WHERE command_key=%s",$key),ARRAY_A);if(''!==(string)$wpdb->last_error){return new WP_Error('gcu_command_read_failed',__('The idempotent command state could not be verified safely. Retry later.','global-clinic-usp-integration'),array('status'=>503));}if(!$row||empty($row['request_hash'])||!hash_equals((string)$row['request_hash'],$request_hash)){return new WP_Error('gcu_idempotency_payload_conflict',__('This idempotency key is already bound to a different or legacy request. Use a new key.','global-clinic-usp-integration'),array('status'=>409));}if('complete'===$row['status']){$r=json_decode((string)$row['result_json'],true);return is_array($r)?$r:array();}$stale=!empty($row['locked_at'])&&strtotime($row['locked_at'].' UTC')<time()-300;if('processing'===$row['status']&&!$stale||(int)$row['attempts']>=3){return new WP_Error('gcu_command_conflict',__('This command is already processing or has exhausted its safe retries.','global-clinic-usp-integration'),array('status'=>409));}$claimed=$wpdb->query($wpdb->prepare("UPDATE {$t['commands']} SET status='processing',attempts=attempts+1,error_code=NULL,locked_at=%s,updated_at=%s WHERE command_key=%s AND request_hash=%s AND (status='failed' OR (status='processing' AND locked_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 5 MINUTE)))",$now,$now,$key,$request_hash));if(1!==$claimed){return new WP_Error('gcu_command_conflict',__('This command could not be safely reclaimed.','global-clinic-usp-integration'),array('status'=>409));}}$lock=GCU_Hardening::acquire_db_lock('command:'.substr($key,0,40),3);if(!$lock){$this->fail_command_claim($key,$request_hash,$now,'lock_busy');return new WP_Error('gcu_command_lock_busy',__('This command is already being finalized.','global-clinic-usp-integration'),array('status'=>409));}try{if(!$this->begin_owned_transaction()){$this->fail_command($key,'transaction_start');return new WP_Error('gcu_command_transaction_failed',__('The command transaction could not start.','global-clinic-usp-integration'),array('status'=>503));}try{$r=call_user_func($callback);}catch(Throwable$e){$this->rollback_owned_transaction();$this->fail_command($key,'exception');return new WP_Error('gcu_command_failed',__('The command failed safely.','global-clinic-usp-integration'),array('status'=>500));}if(is_wp_error($r)){$this->rollback_owned_transaction();$this->fail_command($key,$r->get_error_code());return$r;}$encoded=wp_json_encode($r);if(false===$encoded||strlen($encoded)>20000){$this->rollback_owned_transaction();$this->fail_command($key,'result_invalid');return new WP_Error('gcu_command_result_invalid',__('The command result could not be stored safely.','global-clinic-usp-integration'),array('status'=>500));}$done=$wpdb->query($wpdb->prepare("UPDATE {$t['commands']} SET status='complete',result_json=%s,error_code=NULL,locked_at=NULL,updated_at=%s WHERE command_key=%s AND request_hash=%s AND status='processing'",$encoded,current_time('mysql',true),$key,$request_hash));if(1!==$done){$this->rollback_owned_transaction();$this->fail_command($key,'completion_failed');return new WP_Error('gcu_command_completion_failed',__('The command result could not be committed safely.','global-clinic-usp-integration'),array('status'=>500));}if(!$this->commit_owned_transaction()){$this->fail_command($key,'commit_unknown');return new WP_Error('gcu_command_commit_unknown',__('The command commit could not be confirmed. Retry with the same idempotency key to obtain authoritative status.','global-clinic-usp-integration'),array('status'=>503));}return$r;}finally{GCU_Hardening::release_db_lock($lock);}}
private function fail_command($key,$code){global$wpdb;$t=GCU_Install::tables();$wpdb->query($wpdb->prepare("UPDATE {$t['commands']} SET status='failed',error_code=%s,locked_at=NULL,updated_at=%s WHERE command_key=%s AND status='processing'",sanitize_key($code),current_time('mysql',true),$key));}
private function fail_command_claim($key,$request_hash,$locked_at,$code){global$wpdb;$t=GCU_Install::tables();$wpdb->query($wpdb->prepare("UPDATE {$t['commands']} SET status='failed',error_code=%s,locked_at=NULL,updated_at=%s WHERE command_key=%s AND request_hash=%s AND status='processing' AND locked_at=%s",sanitize_key($code),current_time('mysql',true),$key,$request_hash,$locked_at));}
public function audit($action,$type,$id,$purpose,$reason,array$before,array$after){global$wpdb;$t=GCU_Install::tables();$owned=false;if($this->transaction_active()){if(!$this->transaction_audit_lock){$this->transaction_audit_lock=GCU_Hardening::acquire_db_lock('audit-chain',3);if(!$this->transaction_audit_lock){$this->mark_containment('audit_lock_failed');return false;}}$lock=$this->transaction_audit_lock;}else{$lock=GCU_Hardening::acquire_db_lock('audit-chain',3);$owned=true;if(!$lock){$this->mark_containment('audit_lock_failed');return false;}}try{$wpdb->last_error='';$prev=(string)$wpdb->get_var("SELECT row_hash FROM {$t['audit']} ORDER BY id DESC LIMIT 1");if(''!==(string)$wpdb->last_error){$this->mark_containment('audit_read_failed');return false;}if(''===$prev){$prev=str_repeat('0',64);}elseif(!preg_match('/^[a-f0-9]{64}$/',$prev)){$this->mark_containment('audit_anchor_invalid');return false;}$before_json=$before?wp_json_encode($before):null;$after_json=$after?wp_json_encode($after):null;if(($before&&false===$before_json)||($after&&false===$after_json)){$this->mark_containment('audit_payload_encode_failed');return false;}$r=array('trace_id'=>GCU_Policy::trace_id(),'actor_id'=>get_current_user_id(),'action_name'=>sanitize_key($action),'object_type'=>sanitize_key($type),'object_id'=>GCU_Hardening::bounded_text(sanitize_text_field($id),191),'purpose'=>GCU_Hardening::bounded_text(sanitize_key($purpose),100),'reason'=>GCU_Hardening::bounded_text(sanitize_textarea_field($reason),self::MAX_REASON),'before_hash'=>$before?hash('sha256',$before_json):null,'after_hash'=>$after?hash('sha256',$after_json):null,'previous_hash'=>$prev,'created_at'=>current_time('mysql',true));$r['row_hash']=$this->audit_row_hash($r);if(!$r['row_hash']||false===$wpdb->insert($t['audit'],$r)){$this->mark_containment('audit_write_failed');return false;}return$r['trace_id'];}finally{if($owned){GCU_Hardening::release_db_lock($lock);}}}
private function audit_row_hash(array$r){return GCU_Integrity::stable_audit_row_hash($r);}
public function verify_audit_chain($limit=5000){global$wpdb;$t=GCU_Install::tables();$wpdb->last_error='';$total_raw=$wpdb->get_var("SELECT COUNT(*) FROM {$t['audit']}");if(''!==(string)$wpdb->last_error){return array('valid'=>false,'scope'=>'query_failed','checked'=>0,'total'=>0,'error'=>'count');}$total=(int)$total_raw;$limit=max(1,min(10000,(int)$limit));$offset=max(0,$total-$limit);if(0===$offset){$wpdb->last_error='';$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['audit']} ORDER BY id ASC LIMIT %d",$limit),ARRAY_A);if(''!==(string)$wpdb->last_error||!is_array($rows)){return array('valid'=>false,'scope'=>'query_failed','checked'=>0,'total'=>$total,'error'=>'rows');}$prev=str_repeat('0',64);$scope='full';}else{$wpdb->last_error='';$anchor=(string)$wpdb->get_var($wpdb->prepare("SELECT row_hash FROM {$t['audit']} ORDER BY id ASC LIMIT 1 OFFSET %d",$offset-1));if(''!==(string)$wpdb->last_error){return array('valid'=>false,'scope'=>'query_failed','checked'=>0,'total'=>$total,'error'=>'anchor');}if(!preg_match('/^[a-f0-9]{64}$/',$anchor)){return array('valid'=>false,'scope'=>'anchor_missing','checked'=>0,'total'=>$total);}$wpdb->last_error='';$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['audit']} ORDER BY id ASC LIMIT %d OFFSET %d",$limit,$offset),ARRAY_A);if(''!==(string)$wpdb->last_error||!is_array($rows)){return array('valid'=>false,'scope'=>'query_failed','checked'=>0,'total'=>$total,'error'=>'rows');}$prev=$anchor;$scope='recent_tail';}$checked=0;foreach($rows as$row){$checked++;if(!hash_equals($prev,(string)$row['previous_hash'])||!hash_equals((string)$row['row_hash'],$this->audit_row_hash($row))){return array('valid'=>false,'scope'=>'failed','checked'=>$checked,'total'=>$total,'offset'=>$offset);}$prev=(string)$row['row_hash'];}return array('valid'=>true,'scope'=>$scope,'checked'=>$checked,'total'=>$total,'offset'=>$offset);}
public function publish_event($name,array$payload){global$wpdb;$t=GCU_Install::tables();$id=wp_generate_uuid4();$payload['event_id']=$id;$payload['event_name']=sanitize_text_field($name);$payload['event_version']=1;$payload['occurred_at']=gmdate('c');$payload=GCU_Hardening::sanitize_structured_value($payload);$enc=wp_json_encode($payload);if(false===$enc||strlen($enc)>20000){$this->mark_containment('outbox_payload_invalid');return false;}$ins=$wpdb->insert($t['outbox'],array('event_id'=>$id,'event_name'=>sanitize_text_field($name),'event_version'=>1,'payload'=>$enc,'status'=>'pending','attempts'=>0,'created_at'=>current_time('mysql',true)));if(false===$ins){$this->mark_containment('outbox_write_failed');return false;}if($this->transaction_active()){$this->deferred_event_ids[]=$id;}else{$this->dispatch_outbox($id,1);}return$id;}
public function dispatch_outbox($event_id='',$limit=20){global$wpdb;$t=GCU_Install::tables();$limit=max(1,min(100,(int)$limit));$where="(status IN ('pending','retry') AND (next_attempt_at IS NULL OR next_attempt_at<=UTC_TIMESTAMP())) OR (status='processing' AND locked_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 10 MINUTE))";$args=array();if($event_id){$where="event_id=%s AND ($where)";$args[]=sanitize_text_field($event_id);}$sql="SELECT * FROM {$t['outbox']} WHERE $where ORDER BY id ASC LIMIT $limit";$wpdb->last_error='';$rows=$args?$wpdb->get_results($wpdb->prepare($sql,$args),ARRAY_A):$wpdb->get_results($sql,ARRAY_A);if(''!==(string)$wpdb->last_error||!is_array($rows)){GCU_Observability::log('error','outbox_select_failed',array());return 0;}foreach($rows as$row){$claim=$wpdb->query($wpdb->prepare("UPDATE {$t['outbox']} SET status='processing',locked_at=%s,attempts=attempts+1 WHERE id=%d AND ((status IN ('pending','retry') AND (next_attempt_at IS NULL OR next_attempt_at<=UTC_TIMESTAMP())) OR (status='processing' AND locked_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 10 MINUTE)))",current_time('mysql',true),(int)$row['id']));if(false===$claim){GCU_Observability::log('error','outbox_claim_failed',array('row_id'=>(int)$row['id']));continue;}if(1!==$claim){continue;}try{do_action($row['event_name'],json_decode((string)$row['payload'],true));$finalized=$wpdb->query($wpdb->prepare("UPDATE {$t['outbox']} SET status='sent',locked_at=NULL,next_attempt_at=NULL,last_error_code=NULL,dispatched_at=%s WHERE id=%d AND status='processing'",current_time('mysql',true),(int)$row['id']));if(1!==$finalized){GCU_Observability::log('error','outbox_finalize_failed',array('row_id'=>(int)$row['id']));}}catch(Throwable$e){$attempt=(int)$row['attempts']+1;$status=$attempt>=5?'dead':'retry';$delay=min(3600,60*(1<<min(5,$attempt)));$retry_saved=$wpdb->query($wpdb->prepare("UPDATE {$t['outbox']} SET status=%s,locked_at=NULL,next_attempt_at=%s,last_error_code='dispatch_exception' WHERE id=%d AND status='processing'",$status,gmdate('Y-m-d H:i:s',time()+$delay),(int)$row['id']));if(1!==$retry_saved){GCU_Observability::log('error','outbox_retry_state_failed',array('row_id'=>(int)$row['id']));}}}return count($rows);}
public function accept_inbound_event($name,array$payload){$ready=GCU_Install::ready_for_mutation();if(is_wp_error($ready)){return false;}$v=$this->validate_inbound_event($name,$payload);if(is_wp_error($v)){return false;}global$wpdb;$t=GCU_Install::tables();$clean=GCU_Hardening::sanitize_structured_value($payload);$enc=wp_json_encode($clean);if(false===$enc){return false;}$hash=hash('sha256',$enc);$event_id=sanitize_text_field($payload['event_id']);$event_name=sanitize_text_field($name);$ins=$wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$t['inbox']} (event_id,event_name,payload_hash,payload,status,attempts,created_at) VALUES (%s,%s,%s,%s,'pending',0,%s)",$event_id,$event_name,$hash,$enc,current_time('mysql',true)));if(false===$ins){return false;}if(0===$ins){$existing=$wpdb->get_row($wpdb->prepare("SELECT event_name,payload_hash FROM {$t['inbox']} WHERE event_id=%s",$event_id),ARRAY_A);if(!$existing||!hash_equals((string)$existing['payload_hash'],$hash)||!hash_equals((string)$existing['event_name'],$event_name)){GCU_Observability::log('warning','inbound_event_identity_conflict',array('event_id'=>$event_id,'event_name'=>$event_name));return false;}}if(1===$ins){$this->process_inbox($event_id,1);}return true;}
private function validate_inbound_event($name,array$p){if(!in_array($name,array('DoctorDirectoryAvailable.v1','ClinicBookingAvailable.v1','DoctorOnboardingAvailable.v1','BusinessPolicyChanged.v1'),true)||empty($p['event_id'])||!wp_is_uuid($p['event_id'])){return new WP_Error('gcu_inbound_schema_invalid','Invalid event envelope.');}if('BusinessPolicyChanged.v1'!==$name){if(!array_key_exists('available',$p)||!is_bool($p['available'])){return new WP_Error('gcu_inbound_schema_invalid','Availability events require a boolean available field.');}if(!empty($p['url'])&&!GCU_Hardening::strict_same_origin_url($p['url'])){return new WP_Error('gcu_inbound_url_invalid','Availability event URL is not same-origin.');}}return true;}
public function process_inbox($event_id='',$limit=20){global$wpdb;$t=GCU_Install::tables();$limit=max(1,min(100,(int)$limit));$where="(status IN ('pending','retry') AND (next_attempt_at IS NULL OR next_attempt_at<=UTC_TIMESTAMP())) OR (status='processing' AND locked_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 10 MINUTE))";$args=array();if($event_id){$where="event_id=%s AND ($where)";$args[]=sanitize_text_field($event_id);}$sql="SELECT * FROM {$t['inbox']} WHERE $where ORDER BY id ASC LIMIT $limit";$wpdb->last_error='';$rows=$args?$wpdb->get_results($wpdb->prepare($sql,$args),ARRAY_A):$wpdb->get_results($sql,ARRAY_A);if(''!==(string)$wpdb->last_error||!is_array($rows)){GCU_Observability::log('error','inbox_select_failed',array());return 0;}foreach($rows as$row){$claim=$wpdb->query($wpdb->prepare("UPDATE {$t['inbox']} SET status='processing',locked_at=%s,attempts=attempts+1 WHERE id=%d AND ((status IN ('pending','retry') AND (next_attempt_at IS NULL OR next_attempt_at<=UTC_TIMESTAMP())) OR (status='processing' AND locked_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 10 MINUTE)))",current_time('mysql',true),(int)$row['id']));if(false===$claim){GCU_Observability::log('error','inbox_claim_failed',array('row_id'=>(int)$row['id']));continue;}if(1!==$claim){continue;}try{$r=GCU_Plugin::instance()->contracts()->apply_inbound_event($row['event_name'],json_decode((string)$row['payload'],true));if(is_wp_error($r)){throw new RuntimeException($r->get_error_code());}$finalized=$wpdb->query($wpdb->prepare("UPDATE {$t['inbox']} SET status='processed',locked_at=NULL,next_attempt_at=NULL,last_error_code=NULL,processed_at=%s WHERE id=%d AND status='processing'",current_time('mysql',true),(int)$row['id']));if(1!==$finalized){GCU_Observability::log('error','inbox_finalize_failed',array('row_id'=>(int)$row['id']));}}catch(Throwable$e){$attempt=(int)$row['attempts']+1;$status=$attempt>=5?'dead':'retry';$delay=min(3600,60*(1<<min(5,$attempt)));$retry_saved=$wpdb->query($wpdb->prepare("UPDATE {$t['inbox']} SET status=%s,locked_at=NULL,next_attempt_at=%s,last_error_code='process_exception' WHERE id=%d AND status='processing'",$status,gmdate('Y-m-d H:i:s',time()+$delay),(int)$row['id']));if(1!==$retry_saved){GCU_Observability::log('error','inbox_retry_state_failed',array('row_id'=>(int)$row['id']));}}}return count($rows);}
private function delete_batches($sql,$max_batches=20){global$wpdb;$total=0;for($i=0;$i<$max_batches;$i++){$n=$wpdb->query($sql);if(false===$n){return false;}$total+=(int)$n;if((int)$n<500){return$total;}}GCU_Observability::log('warning','lifecycle_cleanup_backlog',array('deleted'=>$total));return$total;}
private function cleanup_expired_events_with_holds($max_batches=20){global$wpdb;$t=GCU_Install::tables();$total=0;$cursor=0;for($i=0;$i<$max_batches;$i++){$wpdb->last_error='';$rows=$wpdb->get_results($wpdb->prepare("SELECT id,subject_hash FROM {$t['events']} WHERE occurred_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL %d DAY) AND id>%d ORDER BY id ASC LIMIT 500",self::EVENT_RETENTION_DAYS,$cursor),ARRAY_A);if(''!==(string)$wpdb->last_error||!is_array($rows)){return false;}if(!$rows){return$total;}$ids=array();foreach($rows as$row){$cursor=max($cursor,(int)$row['id']);if(!GCU_Privacy::legal_hold_applies('conversion_event',(string)$row['subject_hash'])){$ids[]=(int)$row['id'];}}if($ids){$placeholders=implode(',',array_fill(0,count($ids),'%d'));$sql=$wpdb->prepare("DELETE FROM {$t['events']} WHERE id IN ($placeholders)",$ids);$n=$wpdb->query($sql);if(false===$n){return false;}$total+=(int)$n;}if(count($rows)<500){return$total;}}GCU_Observability::log('warning','event_retention_scan_backlog',array('deleted'=>$total,'cursor'=>$cursor));return$total;}
public function cleanup_lifecycle(){global$wpdb;$t=GCU_Install::tables();$result=array('tokens'=>$this->delete_batches("DELETE FROM {$t['event_tokens']} WHERE expires_at<UTC_TIMESTAMP() OR consumed_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 DAY) LIMIT 500"),'rate_limits'=>$this->delete_batches("DELETE FROM {$t['rate_limits']} WHERE expires_at<UTC_TIMESTAMP() LIMIT 500"),'events'=>$this->cleanup_expired_events_with_holds(),'outbox'=>$this->delete_batches("DELETE FROM {$t['outbox']} WHERE status='sent' AND dispatched_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY) LIMIT 500"),'inbox'=>$this->delete_batches("DELETE FROM {$t['inbox']} WHERE status='processed' AND processed_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY) LIMIT 500"),'commands'=>$this->delete_batches("DELETE FROM {$t['commands']} WHERE status='complete' AND updated_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 7 DAY) LIMIT 500"));if(in_array(false,$result,true)){GCU_Observability::log('error','lifecycle_cleanup_failed',array('result'=>$result));}return$result;}
private function sanitize_datetime($v){$v=sanitize_text_field((string)$v);if(''===$v){return null;}$t=strtotime($v.' UTC');return$t?gmdate('Y-m-d H:i:s',$t):null;}
}
